//! The ThingWorx 10.2 widget catalogue: what a widget is called, the properties Composer gives it
//! when it is dropped on a mashup, and, for the PTCS widgets, which properties bind which way and
//! which events and services it has.
//!
//! The catalogue is for ThingWorx 10.2 only. `widgets/catalog.json` is generated by hand from a 10.2
//! installation by `scripts/generate_widget_catalog.mjs` (which records the SHA-256 of what it read),
//! plus the curated `scripts/widget_catalog_overlay.json`; it is never edited by hand. A widget
//! without a contract (a container) can be placed but not bound. Properties a widget makes up from
//! its own configuration (a KPI's thresholds, a collection's mashup parameters) are not in it.

use crate::core::codes::{Coded, ErrorCode};
use serde::Deserialize;
use serde_json::{Map, Value};
use std::collections::{BTreeMap, BTreeSet};
use std::sync::LazyLock;

const CATALOG: &str = include_str!("widgets/catalog.json");

/// The platform the catalogue describes.
pub(crate) const PLATFORM: &str = "10.2";

#[derive(Debug, Deserialize)]
pub struct Catalog {
    #[allow(
        dead_code,
        reason = "deserialised from the embedded catalogue; checked only by tests"
    )]
    pub(crate) platform: String,
    /// Properties every widget has, whatever its contract says.
    pub(crate) base_properties: BTreeMap<String, PropertyContract>,
    /// What Composer writes on a dropped widget after its defaults.
    pub(crate) dropped: Dropped,
    /// Every widget type the platform ships, including those without a contract here.
    pub(crate) platform_types: BTreeSet<String>,
    pub(crate) widgets: Vec<Widget>,
}

#[derive(Debug, Deserialize)]
pub(crate) struct Dropped {
    /// On every PTCS widget.
    pub(crate) ptcs: Map<String, Value>,
    pub(crate) flexcontainer: Map<String, Value>,
}

#[derive(Debug, Deserialize)]
pub struct Widget {
    /// The `Type` a mashup writes, e.g. `ptcsbutton`.
    #[serde(rename = "type")]
    pub(crate) type_id: String,
    pub(crate) aliases: Vec<String>,
    /// Composer's label, written as `__TypeDisplayName`.
    pub type_display_name: String,
    /// The `DisplayName` stem: a dropped widget is `<display_name>-<n>`, or just this when it is
    /// not `numbered`.
    pub(crate) display_name: String,
    pub(crate) numbered: bool,
    /// Whether other widgets go inside it.
    pub(crate) container: bool,
    /// Whether it can fill the container it is alone in (Composer's `supportsAutoResize`).
    #[serde(default)]
    pub(crate) auto_resize: bool,
    /// Composer's defaults, in Composer's order.
    pub(crate) defaults: Map<String, Value>,
    /// The binding contract; absent for a widget whose contract the catalogue does not know.
    pub(crate) properties: Option<BTreeMap<String, PropertyContract>>,
    pub(crate) events: Option<Vec<String>>,
    pub(crate) services: Option<Vec<String>>,
    /// A function widget (expression, validator, navigation, ...): it sits under the mashup root,
    /// beside the layout, and draws nothing.
    #[serde(default)]
    pub function: bool,
    /// A legacy widget that stays readable in existing mashups; adding one adds this instead.
    #[serde(default)]
    pub(crate) replaced_by: Option<String>,
}

#[derive(Clone, Debug, Deserialize, PartialEq)]
pub(crate) struct PropertyContract {
    pub(crate) base_type: Option<String>,
    /// Can be bound from: the widget sets it.
    #[serde(default)]
    pub(crate) source: bool,
    /// Can be bound to: something else sets it.
    #[serde(default)]
    pub(crate) target: bool,
    #[serde(default = "yes")]
    pub(crate) editable: bool,
    /// The values a select property allows, when it lists them.
    #[serde(default)]
    pub(crate) options: Vec<Value>,
}

const fn yes() -> bool {
    true
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum CatalogError {
    #[error("no widget is called `{word}` in the ThingWorx {PLATFORM} catalogue{}", hint(.close))]
    Unknown { word: String, close: Vec<String> },
}

fn hint(close: &[String]) -> String {
    if close.is_empty() {
        "; `twaco widgets` lists them".to_string()
    } else {
        format!("; did you mean {}?", close.join(", "))
    }
}

impl Coded for CatalogError {
    fn code(&self) -> ErrorCode {
        ErrorCode::InvalidArguments
    }
}

static PARSED: LazyLock<Catalog> = LazyLock::new(|| {
    serde_json::from_str(CATALOG).expect("the embedded widget catalogue is valid; a test checks it")
});

/// The embedded catalogue.
pub fn catalog() -> &'static Catalog {
    &PARSED
}

impl Catalog {
    /// The widget with this exact `Type`.
    pub fn by_type(&self, type_id: &str) -> Option<&Widget> {
        self.widgets.iter().find(|widget| widget.type_id == type_id)
    }

    /// The widget a person names: its type or an alias, ignoring case.
    pub(crate) fn resolve(&self, word: &str) -> Result<&Widget, CatalogError> {
        let wanted = word.trim().to_ascii_lowercase();
        self.widgets
            .iter()
            .find(|widget| {
                widget
                    .names()
                    .any(|name| name.eq_ignore_ascii_case(&wanted))
            })
            // A legacy widget's word adds its replacement (`expression` adds `expression2`).
            .map(|widget| {
                widget
                    .replaced_by
                    .as_deref()
                    .and_then(|replacement| self.by_type(replacement))
                    .unwrap_or(widget)
            })
            .ok_or_else(|| CatalogError::Unknown {
                word: word.to_string(),
                close: self
                    .search(&wanted)
                    .into_iter()
                    .take(5)
                    .map(|widget| widget.type_id.clone())
                    .collect(),
            })
    }

    /// Widgets whose type, alias or label contains `text`, ignoring case; all of them for "".
    pub(crate) fn search(&self, text: &str) -> Vec<&Widget> {
        let wanted = text.trim().to_ascii_lowercase();
        self.widgets
            .iter()
            .filter(|widget| {
                widget
                    .names()
                    .chain(std::iter::once(widget.type_display_name.as_str()))
                    .any(|name| name.to_ascii_lowercase().contains(&wanted))
            })
            .collect()
    }
}

impl Widget {
    /// Its type and aliases.
    pub(crate) fn names(&self) -> impl Iterator<Item = &str> {
        std::iter::once(self.type_id.as_str()).chain(self.aliases.iter().map(String::as_str))
    }

    /// Whether the catalogue knows what its properties and events are.
    pub(crate) fn has_contract(&self) -> bool {
        self.properties.is_some()
    }

    /// A property's contract, the widget's own or one every widget has. `None` when the widget has
    /// no contract or no such property.
    pub(crate) fn property(&self, name: &str) -> Option<&PropertyContract> {
        let own = self.properties.as_ref()?;
        own.get(name)
            .or_else(|| catalog().base_properties.get(name))
    }

    pub(crate) fn has_event(&self, name: &str) -> bool {
        self.events
            .as_ref()
            .is_some_and(|events| events.iter().any(|event| event == name))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    #[test]
    fn the_embedded_catalogue_is_for_10_2_and_every_widget_has_composer_defaults() {
        let catalog = catalog();
        assert_eq!(catalog.platform, PLATFORM);
        assert!(catalog.widgets.len() >= 40, "{}", catalog.widgets.len());
        for widget in &catalog.widgets {
            assert!(!widget.defaults.is_empty(), "{}", widget.type_id);
            assert!(!widget.type_display_name.is_empty(), "{}", widget.type_id);
            assert!(!widget.display_name.is_empty(), "{}", widget.type_id);
        }
        let source: Value = serde_json::from_str(CATALOG).unwrap();
        for input in ["widget_meta_values", "widget_contracts"] {
            let sha = source["source"][input]["sha256"].as_str().unwrap();
            assert_eq!(
                sha.len(),
                64,
                "{input} records the SHA-256 of what it was made from"
            );
        }
    }

    #[test]
    fn every_name_means_one_widget_whatever_its_case() {
        let mut seen = BTreeSet::new();
        for widget in &catalog().widgets {
            for name in widget.names() {
                assert!(
                    seen.insert(name.to_ascii_lowercase()),
                    "{name} names two widgets"
                );
            }
        }
    }

    #[test]
    fn a_widget_is_found_by_type_or_alias_and_an_unknown_one_suggests_others() {
        let catalog = catalog();
        assert_eq!(catalog.resolve("ptcsgrid").unwrap().type_id, "ptcsgrid");
        assert_eq!(catalog.resolve("Grid").unwrap().type_id, "ptcsgrid");
        assert_eq!(catalog.resolve(" table ").unwrap().type_id, "ptcsgrid");
        assert_eq!(
            catalog.resolve("container").unwrap().type_id,
            "flexcontainer"
        );
        let error = catalog.resolve("chart").unwrap_err();
        let CatalogError::Unknown { close, .. } = &error;
        assert!(close.iter().any(|c| c == "ptcschartbar"), "{close:?}");
        assert_eq!(error.code(), ErrorCode::InvalidArguments);
        assert!(catalog
            .resolve("gizmo")
            .unwrap_err()
            .to_string()
            .contains("twaco widgets"));
    }

    #[test]
    fn defaults_keep_composers_order() {
        let button = catalog().by_type("ptcsbutton").unwrap();
        let keys: Vec<&str> = button.defaults.keys().map(String::as_str).collect();
        assert_eq!(&keys[..3], ["Area", "ButtonType", "ContextID"]);
        assert_eq!(button.defaults["Label"], Value::from("[[Button]]"));
    }

    #[test]
    fn the_contracts_agents_bind_most_are_as_the_10_2_bundle_declares_them() {
        let catalog = catalog();
        let contract = |widget: &str, property: &str| {
            let found = catalog.by_type(widget).unwrap().property(property).unwrap();
            (found.base_type.clone().unwrap(), found.source, found.target)
        };
        assert_eq!(
            contract("ptcsgrid", "Data"),
            ("INFOTABLE".into(), false, true)
        );
        assert_eq!(
            contract("ptcstextfield", "Text"),
            ("STRING".into(), true, true)
        );
        assert_eq!(
            contract("ptcsdropdown", "SelectedText"),
            ("STRING".into(), true, true)
        );
        assert_eq!(
            contract("ptcsmenubar", "PrimaryNavData"),
            ("INFOTABLE".into(), false, true)
        );
        assert!(catalog.by_type("ptcsgrid").unwrap().auto_resize);
        assert!(!catalog.by_type("ptcsbutton").unwrap().auto_resize);
    }

    #[test]
    fn contracts_say_which_way_a_property_binds() {
        let catalog = catalog();
        let grid = catalog.by_type("ptcsgrid").unwrap();
        let data = grid.property("Data").unwrap();
        assert_eq!(
            (data.base_type.as_deref(), data.target),
            (Some("INFOTABLE"), true)
        );
        let text = catalog
            .by_type("ptcstextfield")
            .unwrap()
            .property("Text")
            .unwrap();
        assert!(text.source && text.target, "{text:?}");
        // Every widget has Visible, though no contract lists it.
        assert!(grid.property("Visible").unwrap().target);
        assert!(catalog.by_type("ptcsbutton").unwrap().has_event("Clicked"));
        // A container has defaults but no contract: it can be placed, not bound.
        let container = catalog.by_type("flexcontainer").unwrap();
        assert!(container.container && !container.has_contract());
        assert!(container.property("Visible").is_none());
    }
}
